<?php
session_start(); require_once __DIR__.'/config.php';
if(empty($_SESSION['payment_verified'])||empty($_SESSION['palm_image'])){header('Location: index.php');exit;}
$report=$_SESSION['report']??null;
if(!$report){
  $image=$_SESSION['palm_image']; $name=$_SESSION['customer_name']??'';
  $prompt='You are an experienced traditional palmistry reader. Analyze the provided palm image as an interpretive palmistry reading, not as a scientific diagnosis or guaranteed prediction. Be realistic, balanced, specific and practical. Do not claim certainty. Do not invent visible features if the image is unclear; say when a conclusion is tentative. Create a detailed Hindi report for the customer.'.($name?' Customer name: '.$name.'.':'')."\n\nCover these sections in natural Hindi: overall personality and life pattern; heart line and love/relationship; marriage tendencies and possible delays or turning points without exact guaranteed dates; money, savings and financial patterns; career/job; business and risk-taking; family and responsibilities; property/major assets; opportunities and obstacles; mental pressure and decision-making; next 2-3 years as broad phases rather than exact dates; practical advice. Mention major palm lines (life, head, heart, fate, sun if visible) and mounts (Guru, Shani, Surya, Budh, Shukra, Chandra) only when visually supportable. Avoid medical claims, death predictions, guaranteed wealth, guaranteed marriage, or exact lottery-like outcomes. Use headings and detailed paragraphs. Do not mention that the report was generated by a computer system or model.";
  $parts=parse_url($image); $mime='image/jpeg'; if(strpos($image,'data:image/png')===0)$mime='image/png'; if(strpos($image,'data:image/webp')===0)$mime='image/webp';
  $payload=['model'=>'gpt-4.1-mini','input'=>[['role'=>'user','content'=>[['type'=>'input_text','text'=>$prompt],['type'=>'input_image','image_url'=>$image]]]],'max_output_tokens'=>4500];
  $ch=curl_init('https://api.openai.com/v1/responses');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($payload,JSON_UNESCAPED_UNICODE),CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.OPENAI_API_KEY],CURLOPT_TIMEOUT=>90]);$out=curl_exec($ch);$http=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$data=json_decode($out,true);
  $text=''; if(isset($data['output'])){foreach($data['output'] as $item){foreach(($item['content']??[]) as $c){if(isset($c['text']))$text.=$c['text'];}}} if(!$text && isset($data['output_text']))$text=$data['output_text'];
  if($http<200||$http>=300||!$text){$text='आपकी रिपोर्ट इस समय तैयार नहीं हो सकी। कृपया कुछ देर बाद फिर प्रयास करें।';}
  $report=$text;$_SESSION['report']=$report;
}
function esc($s){return htmlspecialchars($s,ENT_QUOTES,'UTF-8');}
function formatReport($s){$s=preg_replace('/^###\s*(.+)$/m','<h3>$1</h3>',$s);$s=preg_replace('/^##\s*(.+)$/m','<h2>$1</h2>',$s);$s=preg_replace('/^#\s*(.+)$/m','<h2>$1</h2>');$s=nl2br($s);return $s;}
